// ============================================
// EntreSkillHub - Home Page (Temporary Beautiful)
// Full KHATARNAK version coming next!
// ============================================

import React from 'react';
import { Link } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { FiArrowRight, FiZap, FiTarget, FiTrendingUp } from 'react-icons/fi';

const HomePage = () => {
  return (
    <>
      <Helmet>
        <title>EntreSkillHub - Transform Your Skills Into Business</title>
        <meta name="description" content="Turn your skills into successful micro-businesses with expert mentorship, roadmaps, and learning resources." />
      </Helmet>

      <div className="min-h-screen bg-gradient-to-br from-dark-900 via-primary-900/20 to-dark-900 relative overflow-hidden">
        {/* Animated Background Blobs */}
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
          <div className="absolute -top-40 -left-40 w-96 h-96 bg-primary-500/20 rounded-full blur-3xl animate-blob"></div>
          <div className="absolute top-1/3 -right-40 w-96 h-96 bg-secondary-500/20 rounded-full blur-3xl animate-blob animation-delay-2000"></div>
          <div className="absolute bottom-0 left-1/3 w-96 h-96 bg-accent-500/20 rounded-full blur-3xl animate-blob animation-delay-4000"></div>
        </div>

        {/* Grid Pattern */}
        <div className="absolute inset-0 bg-grid opacity-30"></div>

        {/* Content */}
        <div className="relative z-10 min-h-screen flex flex-col items-center justify-center px-4 py-20">
          <div className="max-w-6xl mx-auto text-center">
            {/* Badge */}
            <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-white/10 backdrop-blur-xl border border-white/20 text-white text-sm font-medium mb-8 animate-fade-in-down">
              <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
              🎉 Welcome to the Future of Entrepreneurship
            </div>

            {/* Main Heading */}
            <h1 className="text-5xl sm:text-7xl lg:text-8xl font-bold font-display mb-6 animate-fade-in-up">
              <span className="text-white block mb-2">Transform Your</span>
              <span className="gradient-text block">Skills to Startup</span>
            </h1>

            {/* Subtitle */}
            <p className="text-lg sm:text-xl lg:text-2xl text-dark-300 mb-10 max-w-3xl mx-auto animate-fade-in-up animate-delay-200 leading-relaxed">
              Discover personalized business ideas, follow step-by-step roadmaps, and connect with expert mentors to build your dream business.
            </p>

            {/* CTA Buttons */}
            <div className="flex flex-col sm:flex-row items-center justify-center gap-4 mb-16 animate-fade-in-up animate-delay-300">
              <Link to="/register" className="btn-primary btn-xl group">
                Get Started Free
                <FiArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
              </Link>
              <Link to="/business-ideas" className="btn-glass btn-xl">
                Explore Business Ideas
              </Link>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-6 max-w-4xl mx-auto mb-20 animate-fade-in-up animate-delay-500">
              {[
                { value: '10K+', label: 'Entrepreneurs' },
                { value: '500+', label: 'Business Ideas' },
                { value: '200+', label: 'Expert Mentors' },
                { value: '95%', label: 'Success Rate' },
              ].map((stat, i) => (
                <div
                  key={i}
                  className="card-glass p-6 text-center hover:scale-105 transition-transform"
                >
                  <div className="text-4xl font-bold gradient-text mb-2">{stat.value}</div>
                  <div className="text-dark-300 text-sm">{stat.label}</div>
                </div>
              ))}
            </div>

            {/* Feature Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl mx-auto animate-fade-in-up animate-delay-700">
              {[
                {
                  icon: FiZap,
                  title: 'Smart Matching',
                  description: 'AI-powered recommendations based on your skills',
                  gradient: 'from-yellow-500 to-orange-500',
                },
                {
                  icon: FiTarget,
                  title: 'Clear Roadmaps',
                  description: 'Step-by-step guidance from idea to launch',
                  gradient: 'from-purple-500 to-pink-500',
                },
                {
                  icon: FiTrendingUp,
                  title: 'Track Growth',
                  description: 'Visual dashboards and achievement badges',
                  gradient: 'from-green-500 to-emerald-500',
                },
              ].map((feature, i) => (
                <div
                  key={i}
                  className="card-glass p-8 text-left hover:scale-105 transition-all hover:shadow-neon"
                >
                  <div
                    className={`w-14 h-14 rounded-2xl bg-gradient-to-br ${feature.gradient} flex items-center justify-center mb-4`}
                  >
                    <feature.icon className="w-7 h-7 text-white" />
                  </div>
                  <h3 className="text-2xl font-bold text-white mb-2">{feature.title}</h3>
                  <p className="text-dark-300">{feature.description}</p>
                </div>
              ))}
            </div>

            {/* Bottom Message */}
            <div className="mt-20 animate-fade-in-up animate-delay-1000">
              <p className="text-dark-400 mb-4">Join thousands of successful entrepreneurs</p>
              <div className="flex items-center justify-center gap-2 text-yellow-500 text-2xl">
                ⭐⭐⭐⭐⭐
                <span className="text-white text-lg ml-2">4.9/5 Rating</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

export default HomePage;
